class Solution {
  public long maxMatrixSum(int[][] matrix) {
    long sum = 0, minimum = Long.MAX_VALUE;
    int negatives = 0;
    for (int[] row : matrix)
      for (int value : row) {
        if (value < 0) negatives++;
        long absolute = Math.abs((long) value);
        sum += absolute;
        minimum = Math.min(minimum, absolute);
      }
    return (negatives % 2 == 0) ? sum : sum - 2 * minimum;
  }
}
